	regionKind = "place",
	kind = "region",
	sections = {
		{
			title = "Summary",
			text = [=[Northwatch Hold is a stone fortress of the {link:alliance}Alliance{/link} on a hill above the southern {link:the-merchant-coast}Merchant Coast{/link}. {link:humans}Humans{/link} raised it after the war at {link:mount-hyjal}Mount Hyjal{/link}, and Admiral {link:daelin-proudmoore}Daelin Proudmoore{/link} made use of it in his war against the {link:horde}Horde{/link}. Today it is held by soldiers of {link:theramore-isle}Theramore{/link} under {link:captain-fairmount}Captain Fairmount{/link}. Its marines are nervous and quick to fire. Their cannons have sunk more than one ship bound for {link:ratchet}Ratchet{/link}, and they keep prisoners whom they call threats to the Alliance, some of them no more than deckhands. To the orcs, its walls are a spear pointed at the heart of the {link:the-barrens}Barrens{/link}.]=],
		},
	},
