			title = "Summary",
			text = [=[Thorn Hill rises east of the {link:the-crossroads}Crossroads{/link}, between the town and the road to {link:durotar}Durotar{/link}. Its slopes are wrapped in the great thorn vines of the {link:razormane-quilboar}Razormane quilboar{/link}. From here the raider {link:kreenig-snarlsnout}Kreenig Snarlsnout{/link} struck at the caravans from Durotar and grew fat on the supplies of the {link:horde}Horde{/link}. Worse lurks in a cave on the plateau. The {link:quilboar}quilboar{/link} speak of {link:chol-aruk}Chol'aruk{/link}, the Ravener, a monstrous beast of their own kind that no one believed in until warriors went in to find it.]=],
		},
	},
})

