	kind = "region",
	sections = {
		{
			title = "Summary",
			text = [=[The Raptor Grounds are a small valley south of {link:ratchet}Ratchet{/link} and west of {link:northwatch-hold}Northwatch Hold{/link}. The sunscale raptors keep their nests here, and they are cleverer than raptors have any right to be. They stole a shipment of silver from the guard tower of the {link:the-crossroads}Crossroads{/link}, the pay of its soldiers, and carried it back to their nests. No one knows what a raptor wants with silver. The goblin Mebok Mizzyrix believes their cunning lies in their horns.]=],
		},
	},
})

