			title = "Summary",
			text = [=[Agama'gor is a camp of the {link:bristleback-quilboar}Bristleback{/link} {link:quilboar}quilboar{/link} in the center of the {link:the-barrens}Barrens{/link}, north of the road that leads west from {link:camp-taurajo}Camp Taurajo{/link}. Its geomancers dig blood-red stones from the earth, which the quilboar carry as totems of strength. Grunts from Camp Taurajo have fought here and not always come home. One of them, Grunt Dogran, lay wounded near the camp while his comrades sent for healing. Across the road, the {link:razormane-quilboar}Razormane{/link} of {link:bramblescar}Bramblescar{/link} watch the Bristleback with hatred.]=],
		},
	},
})

