			type = "subzone",
			name = "Southern Gold Road",
			areas = { 1157 },
		},
	},
	regionKind = "place",
	kind = "region",
	sections = {
		{
			title = "Summary",
			text = [=[The Gold Road is the great highway of the {link:the-barrens}Barrens{/link}. It runs from the {link:the-mor-shan-rampart}Mor'shan Rampart{/link} in the north, through the {link:the-crossroads}Crossroads{/link} and {link:camp-taurajo}Camp Taurajo{/link}, to the {link:the-great-lift}Great Lift{/link} at the edge of {link:thousand-needles}Thousand Needles{/link} in the south. It takes its name from the trade caravans that travel it. Its northern stretch is watched by {link:horde}Horde{/link} towers. Its southern stretch is lonelier, and a walker who strays from it at dusk may end up in a tree with hyenas circling below.]=],
		},
	},
})

