	regionKind = "place",
	kind = "region",
	sections = {
		{
			title = "Summary",
			text = [=[The Dry Hills rise in the far northwest of the {link:the-barrens}Barrens{/link}, the green foothills of the {link:stonetalon-mountains}Stonetalon Mountains{/link}. The Witchwing {link:harpies}harpies{/link} nest here under Serena Bloodfeather and swoop down on the caravans of the northern road. On a ridge above the hills lives a hermit tanner named {link:walton}Walton{/link}, who wants no company. The hunter {link:vrang-wildgore}Vrang Wildgore{/link} keeps his traps in the valley below. Of late, men in the livery of {link:kul-tiras}Kul Tiras{/link} have been seen searching that valley, camped beside a wrecked caravan.]=],
