	sections = {
		{
			title = "Summary",
			text = [=[Gazlowe is the goblin who founded {link:ratchet}Ratchet{/link} and still runs it. He is a builder by trade and a merchant by nature. When the orcs came to {link:kalimdor}Kalimdor{/link}, {link:thrall}Thrall{/link} hired him as the chief engineer of the new nation of {link:durotar}Durotar{/link}, and his crews helped raise the walls of {link:orgrimmar}Orgrimmar{/link}. Thrall paid him well. With that gold, Gazlowe built a port of his own at the mouth of the Southfury River, where anyone may trade so long as they pay.]=],
		},
		{
			title = "Significance",
			text = [=[Gazlowe is the {link:horde}Horde{/link}'s oldest goblin friend. His port is neutral ground, open to the {link:alliance}Alliance{/link} as well, yet his goodwill toward the orcs is well known. Through {link:ratchet}Ratchet{/link} flows much of what the Horde buys from beyond the sea.]=],
