	hint = [=[Speak with the orc who watches the horizon from the Crossroads.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Mankrik is an {link:orcs}orc{/link} warrior of the {link:the-crossroads}Crossroads{/link}. He and his wife were fighting beside the {link:tauren}tauren{/link} in a small camp when the {link:quilboar}quilboar{/link} overran them. She held three of them off alone. He led others away, and when he turned back he saw her fall. Then they brought him down. A tauren druid found him on {link:gold-road}the Gold Road{/link} and tended his wounds. Now he stands at the Crossroads from dawn to dusk, staring at the horizon, and he has killed every quilboar he has met since.]=],
		},
		{
			title = "Significance",
			text = [=[Mankrik's grief is known to everyone who passes through the {link:the-crossroads}Crossroads{/link}. To many he is proof of what the war with the {link:quilboar}quilboar{/link} costs.]=],
		},
		{
			title = "Deeds",
			text = [=[• He has sworn vengeance on the {link:quilboar}quilboar{/link} who took his wife.
• He asks for the tusks of the {link:bristleback-quilboar}Bristleback{/link}, to celebrate their deaths.
• He is building a memorial to her.]=],
		},
	},
	chapters = {
		{
			key = "lost-in-battle",
			title = "Lost in Battle",
			hint = "Search for Mankrik's wife.",
			unlock = {
				{ type = "quest", id = 4921 },
			},
			text = [=[Mankrik asked only for some sign of her. She was found where the fighting had been, and she was dead. He took the news in silence. Then he went back to his watch.]=],
		},
		{
			key = "her-name-is-olgra",
			title = "Her Name Is Olgra",
			hint = "Recover the adornments of Mankrik's wife.",
			unlock = {
				{ type = "quest", id = 95774 },
			},
			text = [=[The healer who saved Mankrik could not save her. Her name was {link:olgra}Olgra{/link}. She had worn many jewels of polished bone, her own works of art, and they were gone from her body. Mankrik asked that they be taken back from the {link:razormane-quilboar}Razormane{/link} who had carried them off, so that he could place them on her memorial and never forget her.]=],
		},
	},
	mentions = {
		{
			text = "Consumed by Hatred",
			unlock = {
				{ type = "quest", id = 899 },
			},
		},
	},
	bonds = {
		{ id = "olgra", name = "Olgra", note = "his wife" },
	},
})

