Add({
	kind = "topic",
	id = "kolkar-centaurs",
	title = "Kolkar Centaurs",
	aliases = { "Kolkar", "Kolkar centaur", "Kolkar tribe" },
	category = "group",
	region = "the-barrens",
	unlock = {
		{ type = "read" },
		{ type = "quest", id = 850 },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Kolkar are a tribe of {link:centaurs}centaur{/link} who roam the {link:the-barrens}Barrens{/link} and the lands around it. Their riders camp beside the oases, hunt the beasts that come to drink and fall upon travellers on the roads. They raided the {link:tauren}tauren{/link} for years before the orcs came, and they have raided the {link:horde}Horde{/link} ever since.]=],
		},
		{
			title = "In These Days",
			text = [=[For a long time the Kolkar of the {link:the-barrens}Barrens{/link} were scattered and disorderly. Now new leaders have risen among them: {link:barak-kodobane}Barak Kodobane{/link} near the {link:the-forgotten-pools}Forgotten Pools{/link}, {link:verog-the-dervish}Verog the Dervish{/link} at the {link:the-stagnant-oasis}Stagnant Oasis{/link}, and {link:hezrul-bloodmark}Hezrul Bloodmark{/link}, the greatest of them, at the {link:lushwater-oasis}Lushwater Oasis{/link}. Under these chieftains the tribe has become a true threat. {link:regthar-deathgate}Regthar Deathgate{/link} hunts them from his bunkers west of the {link:the-crossroads}Crossroads{/link}, and when their leaders fell, a war band came from the Kolkar homeland in {link:desolace}Desolace{/link} to take revenge. In {link:durotar}Durotar{/link}, another band holds the rocky gorge of {link:kolkar-crag}Kolkar Crag{/link}.]=],
		},
	},
})

